from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # A full-width/full-height solid line separates two equal-sized panels.
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1 and (h - 1) % 2 == 0 and r == (h - 1) // 2:
            split = ("h", r)
            break
    if split is None:
        for c in range(w):
            if all(row[c] == grid[0][c] for row in grid) and (w - 1) % 2 == 0 and c == (w - 1) // 2:
                split = ("v", c)
                break
    if split is None:
        raise ValueError("no centered solid separator")

    orient, k = split
    if orient == "v":
        first = [row[:k] for row in grid]
        second = [row[k + 1:] for row in grid]
    else:
        first = grid[:k]
        second = grid[k + 1:]

    def mode(panel):
        counts = Counter(v for row in panel for v in row)
        return counts.most_common(1)[0][0]

    base = mode(first)
    second_base = mode(second)
    return [[3 if second[r][c] != second_base else base
             for c in range(len(second[0]))] for r in range(len(second))]

